import{_ as e,c as t,o,a4 as c}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q9：useEffect 完全指南","description":"","frontmatter":{},"headers":[],"relativePath":"react/q9.md","filePath":"react/q9.md","lastUpdated":null}'),s={name:"react/q9.md"},a=c('<h1 id="q9-useeffect-完全指南" tabindex="-1">Q9：<code>useEffect</code> 完全指南 <a class="header-anchor" href="#q9-useeffect-完全指南" aria-label="Permalink to &quot;Q9：`useEffect` 完全指南&quot;">​</a></h1><p><code>useEffect(setup, dependencies?)</code> 管理副作用。</p><ul><li><strong>执行时机</strong>：在浏览器完成布局与绘制之后<strong>异步执行</strong>，不阻塞屏幕更新（而 <code>useLayoutEffect</code> 在 DOM 变更后同步触发）。</li><li><strong>清除函数</strong>：setup 返回的函数会在组件卸载以及下一次 effect 执行前运行，用于清除定时器、取消订阅。</li><li><strong>依赖数组</strong>： <ul><li>不传：每次渲染后都执行。</li><li><code>[]</code> 空数组：仅在挂载时执行，卸载时清除。</li><li><code>[a, b]</code>：当依赖值变化时重新执行。</li></ul></li><li><strong>注意</strong>：不要遗漏依赖，否则可能读到过期的闭包变量；不要将对象或函数直接放在依赖中（每次新引用），需借助 <code>useMemo</code>/<code>useCallback</code>。</li></ul>',3),r=[a];function l(d,n,i,_,f,u){return o(),t("div",null,r)}const h=e(s,[["render",l]]);export{g as __pageData,h as default};
